from pyspark.sql import functions as F


def solve(encounters):
    vitals = F.struct(
        F.col("vitals.systolic").alias("systolic"),
        F.col("vitals.diastolic").alias("diastolic"),
        F.col("vitals.heart_rate").alias("pulse"),
    )
    return encounters.select("encounter_id", "encounter_class", vitals.alias("vitals"))
